#include <bits/stdc++.h>
using namespace std;
int margin(vector<unsigned long long> out,int n){int best=-10000; vector<unsigned long long> in(n);for(int u=0;u<n;u++)for(int v=0;v<n;v++)if(out[u]>>v&1)in[v]|=1ULL<<u;
for(int u=0;u<n;u++)if(out[u]){auto del=out[u]|(1ULL<<u);int cnt=0;for(int v=0;v<n;v++)if(!(del>>v&1)&&in[v]&&!(in[v]&~del))cnt++;best=max(best,__builtin_popcountll(out[u])-cnt);}return best;}
int main(){for(int n=2;n<=5;n++){vector<pair<int,int>> pairs;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++)pairs.push_back({u,v});long long total=1;for(auto p:pairs)total*=3;long long checked=0;int worst=100;for(long long code=1;code<total;code++){auto c=code;vector<unsigned long long>a(n);for(auto [u,v]:pairs){int t=c%3;c/=3;if(t==1)a[u]|=1ULL<<v;if(t==2)a[v]|=1ULL<<u;}int m=margin(a,n);worst=min(worst,m);checked++;if(m<0){cout<<"COUNTEREXAMPLE "<<n<<" "<<code<<endl;return 0;}}cout<<"oriented n="<<n<<" checked="<<checked<<" min_best_margin="<<worst<<endl;}
for(int n=2;n<=4;n++){vector<pair<int,int>>p;for(int u=0;u<n;u++)for(int v=0;v<n;v++)if(u!=v)p.push_back({u,v});int total=1<<p.size();for(int c=1;c<total;c++){vector<unsigned long long>a(n);for(int k=0;k<(int)p.size();k++)if(c>>k&1)a[p[k].first]|=1ULL<<p[k].second;if(margin(a,n)<0){cout<<"COUNTEREXAMPLE digraph "<<n<<" "<<c<<endl;return 0;}}cout<<"digraph n="<<n<<" checked="<<total-1<<endl;}
mt19937 rng(180);for(int n:{6,8,12,20,40,60}){int worst=10000;for(int t=0;t<20000;t++){vector<unsigned long long>a(n);int d=1+rng()%min(10,n-1);for(int u=0;u<n;u++){for(int j=0;j<d;j++){int v=rng()%n;if(v!=u)a[u]|=1ULL<<v;}}if(accumulate(a.begin(),a.end(),0ULL)==0){t--;continue;}int m=margin(a,n);worst=min(worst,m);if(m<0){cout<<"COUNTEREXAMPLE random "<<n<<endl;for(auto x:a)cout<<x<<" ";cout<<endl;return 0;}}cout<<"random n="<<n<<" checked=20000 min_best_margin="<<worst<<endl;}}
